def kanji_to_int(s: str) -> int:
    digit_map = {
        "零": 0, "〇": 0,
        "一": 1, "二": 2, "三": 3, "四": 4,
        "五": 5, "六": 6, "七": 7, "八": 8, "九": 9,
    }
    small_units = {"十": 10, "百": 100, "千": 1000}
    large_units = {"万": 10000, "億": 100000000}

    allowed = set(digit_map) | set(small_units) | set(large_units)

    if not s:
        raise ValueError("empty numeral")

    for ch in s:
        if ch not in allowed:
            raise ValueError(f"invalid character: {ch!r}")

    # Positional notation using only kanji digits, e.g. "一〇二" -> 102.
    if not any(ch in small_units or ch in large_units for ch in s):
        result = 0
        for ch in s:
            result = result * 10 + digit_map[ch]
        return result

    total = 0
    section = 0
    current = None

    for ch in s:
        if ch in digit_map:
            current = digit_map[ch]

        elif ch in small_units:
            unit = small_units[ch]
            if current is None:
                current = 1
            section += current * unit
            current = None

        else:  # large units: 万, 億
            unit = large_units[ch]

            if current is not None:
                section += current
                current = None
            elif section == 0:
                section = 1

            if unit == 10000:
                total += section * 10000
            else:  # unit == 100000000
                total = (total + section) * unit

            section = 0

    total += section
    if current is not None:
        total += current

    return total
